import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"终端 UI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tui.md","filePath":"guide/tui.md","lastUpdated":1793871559000}'),a={name:"guide/tui.md"};function c(l,t,i,h,n,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="终端-ui" tabindex="-1">终端 UI <a class="header-anchor" href="#终端-ui" aria-label="Permalink to &quot;终端 UI&quot;">​</a></h1><p>终端 UI 用 bubbletea + lipgloss 实现，视觉规范按实际落地：顶部圆角标题条、左侧蓝色竖条的用户块、等宽工具行、底部带左边条的输入框。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>发送（Shift+Enter 换行）</td></tr><tr><td><code>Esc</code></td><td>运行中停止当前轮 / 关闭浮层</td></tr><tr><td><code>Ctrl+C</code></td><td>退出</td></tr><tr><td><code>Ctrl+P</code></td><td>打开会话列表（↑/↓、j/k 选择，Enter 打开，d 删除）</td></tr><tr><td><code>Ctrl+E</code></td><td>把当前会话导出为 Markdown 文件</td></tr><tr><td><code>Tab</code></td><td>循环切换权限档：只读 → 标准 → 完全 → 计划</td></tr><tr><td><code>Ctrl+T</code></td><td>循环切换展示档：简洁 → 标准 → 详细 → 完全</td></tr><tr><td><code>a</code> / <code>A</code> / <code>d</code></td><td>权限确认浮层中：允许 / 总是允许 / 拒绝</td></tr></tbody></table><h2 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>显示帮助浮层</td></tr><tr><td><code>/sessions</code></td><td>打开会话列表（等同 Ctrl+P）</td></tr><tr><td><code>/readonly</code></td><td>在「只读浏览」与「可编辑继续」之间切换</td></tr><tr><td><code>/export</code></td><td>导出当前会话为 Markdown（等同 Ctrl+E）</td></tr><tr><td><code>/new</code></td><td>开新会话</td></tr><tr><td><code>/clear</code></td><td>清空当前会话</td></tr><tr><td><code>/model [名字]</code></td><td>列出或切换主模型</td></tr><tr><td><code>/aux [名字]</code></td><td>列出或切换辅助模型（摘要用）</td></tr><tr><td><code>/mode [档位]</code></td><td>查看或切换权限档（<code>read_only</code> / <code>standard</code> / <code>full</code> / <code>plan</code>）</td></tr><tr><td><code>/detail [0-3]</code></td><td>设置展示档</td></tr><tr><td><code>/tools</code></td><td>列出当前可用工具</td></tr><tr><td><code>/todo</code></td><td>查看当前任务的计划清单</td></tr><tr><td><code>/memory</code></td><td>查看长期记忆内容与文件位置</td></tr><tr><td><code>/history &lt;关键词&gt;</code></td><td>在历史会话里检索</td></tr><tr><td><code>/image &lt;路径&gt;</code></td><td>挂一张本地图片到下一句；<code>clear</code> 清空待发队列</td></tr></tbody></table><h2 id="展示档" tabindex="-1">展示档 <a class="header-anchor" href="#展示档" aria-label="Permalink to &quot;展示档&quot;">​</a></h2><p>过程信息的默认可见度可调，避免长任务里工具输出刷屏：</p><table tabindex="0"><thead><tr><th>档位</th><th>工具行</th><th>参数</th><th>结果正文</th><th>思考</th></tr></thead><tbody><tr><td>简洁</td><td>隐藏</td><td>隐藏</td><td>隐藏</td><td>隐藏</td></tr><tr><td>标准</td><td>显示</td><td>显示</td><td>前 40 行</td><td>折叠一行预览</td></tr><tr><td>详细</td><td>显示</td><td>显示</td><td>全文</td><td>全文</td></tr><tr><td>完全</td><td>显示</td><td>显示</td><td>全文</td><td>全文</td></tr></tbody></table><h2 id="交互式权限" tabindex="-1">交互式权限 <a class="header-anchor" href="#交互式权限" aria-label="Permalink to &quot;交互式权限&quot;">​</a></h2><p>标准档位下，<code>bash</code> / <code>write</code> / <code>edit</code> / <code>make_dir</code> / <code>move</code> / <code>copy</code> / <code>delete</code> 等高风险工具执行前会弹出确认浮层：</p><ul><li><code>a</code> 本次允许</li><li><code>A</code> 总是允许（计入本进程白名单，直到退出）</li><li><code>d</code> 或 <code>Esc</code> 拒绝</li></ul><p>只读档位由全局 guard 直接拦截写工具，完全档位跳过确认。</p><h2 id="计划模式" tabindex="-1">计划模式 <a class="header-anchor" href="#计划模式" aria-label="Permalink to &quot;计划模式&quot;">​</a></h2><p><code>/mode plan</code>（或 Tab 循环到「计划」）是「只读 + 先出方案」的组合档：权限按只读执行，同时把 <code>planMode</code> 标记打进运行时，系统提示要求模型先给出可执行的方案并停下等确认，而不是试探性地去写。</p><p>它和只读档的区别是行为约束的方向：只读档只是「不许动手」，计划模式还要求「说清打算怎么动手」——改哪些文件、每处改什么、风险在哪。</p><h2 id="只读浏览模式" tabindex="-1">只读浏览模式 <a class="header-anchor" href="#只读浏览模式" aria-label="Permalink to &quot;只读浏览模式&quot;">​</a></h2><p>用 <code>-view &lt;id&gt;</code> 或会话内 <code>/readonly</code> 进入只读浏览：可滚动查看历史、可用 Ctrl+P 切换会话，但禁止发送新消息、隐藏输入框。适合复盘或演示。</p>',18)])])}const p=d(a,[["render",c]]);export{u as __pageData,p as default};
